import { useState } from "react";
import { api } from "./api";
import { Button, Field, Input } from "./ui";

export function SetupForm() {
  const [siteName, setSiteName] = useState("My Site");
  const [email, setEmail] = useState("owner@local");
  const [password, setPassword] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  return (
    <div className="fk-auth-wrap">
      <form
        className="fk-auth-card"
        onSubmit={(e) => {
          e.preventDefault();
          setBusy(true);
          setError(null);
          void api("/api/setup", {
            method: "POST",
            body: JSON.stringify({ siteName, email, password }),
          })
            .then(() => {
              location.href = "/edit";
            })
            .catch((err: Error) => {
              setError(err.message);
              setBusy(false);
            });
        }}
      >
        <p className="fk-eyebrow">Finnsk</p>
        <h1 className="fk-title" style={{ marginTop: 10 }}>
          Set up your site
        </h1>
        <p className="fk-muted" style={{ marginTop: 8, marginBottom: 22 }}>
          One Cloudflare account. Password auth — no email OTP.
        </p>
        <Field label="Site name">
          <Input value={siteName} onChange={(e) => setSiteName(e.target.value)} required />
        </Field>
        <Field label="Email">
          <Input type="email" value={email} onChange={(e) => setEmail(e.target.value)} required />
        </Field>
        <Field label="Password (min 8)">
          <Input
            type="password"
            minLength={8}
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            required
          />
        </Field>
        {error ? <p className="fk-err">{error}</p> : null}
        <Button
          type="submit"
          disabled={busy}
          style={{ width: "100%", marginTop: 8 }}
          variant="primary"
        >
          {busy ? "Creating…" : "Create site"}
        </Button>
      </form>
    </div>
  );
}

