import { useLayoutEffect, useMemo, useRef, useState } from "react";
import {
  ProposalDocument,
  SiteCanvasPreviewProvider,
  StaticAtomSurfaceProvider,
  WEBSITE_DESIGN_WIDTH_DESKTOP_PX,
  websiteSectionThumbnailAspectRatio,
} from "@proposalengine/proposal-builder";
import type {
  PageBackgroundOverrideV3,
  PageDocumentV3,
  ProposalPageV3,
} from "@proposalengine/proposal-builder/document";
import { Plus } from "lucide-react";
import { Button } from "./ui";

function SectionThumb({
  section,
  index,
  selected,
  backgroundOverride,
  surfaceDefaults,
  animationDefaults,
  onClick,
}: {
  section: ProposalPageV3;
  index: number;
  selected: boolean;
  backgroundOverride?: PageBackgroundOverrideV3;
  surfaceDefaults?: PageDocumentV3["templateSurfaceDefaults"];
  animationDefaults?: PageDocumentV3["templateAnimationDefaults"];
  onClick: () => void;
}) {
  const thumbW = WEBSITE_DESIGN_WIDTH_DESKTOP_PX;
  const aspect = websiteSectionThumbnailAspectRatio(section, thumbW);
  const outerRef = useRef<HTMLDivElement>(null);
  const innerRef = useRef<HTMLDivElement>(null);
  const [scale, setScale] = useState(0.12);
  const [h, setH] = useState(Math.max(48, Math.round((thumbW / Math.max(aspect, 0.01)) * 0.12)));

  const bgOverrides = useMemo(
    () => (backgroundOverride ? { [section.id]: backgroundOverride } : undefined),
    [backgroundOverride, section.id]
  );

  useLayoutEffect(() => {
    const outer = outerRef.current;
    const inner = innerRef.current;
    if (!outer || !inner) return;
    const update = () => {
      const outerW = Math.max(1, outer.offsetWidth);
      const s = outerW / thumbW;
      setScale(s);
      setH(Math.ceil(inner.offsetHeight * s));
    };
    update();
    const ro = new ResizeObserver(update);
    ro.observe(outer);
    ro.observe(inner);
    return () => ro.disconnect();
  }, [section.id, thumbW]);

  return (
    <button
      type="button"
      data-finnsk-section-thumb={section.id}
      className={`fk-section-thumb${selected ? " is-active" : ""}`}
      onClick={onClick}
      aria-current={selected ? "true" : undefined}
    >
      <div ref={outerRef} className="fk-section-thumb-frame" style={{ height: h, minHeight: 44 }}>
        <SiteCanvasPreviewProvider>
          <StaticAtomSurfaceProvider value={true}>
            <div
              className="fk-section-thumb-scale"
              style={{
                width: thumbW,
                transform: `scale(${scale})`,
                transformOrigin: "top left",
              }}
            >
              <div ref={innerRef}>
                <ProposalDocument
                  sections={[section]}
                  sectionBackgroundOverrides={bgOverrides}
                  proposalSurfaceDefaults={surfaceDefaults}
                  proposalAnimationDefaults={animationDefaults}
                  previewInteractive={false}
                  layoutMode="website"
                  fixedLayoutWidthPx={thumbW}
                />
              </div>
            </div>
          </StaticAtomSurfaceProvider>
        </SiteCanvasPreviewProvider>
      </div>
      <span className="fk-section-thumb-label">Section {index + 1}</span>
    </button>
  );
}

/** Motion-mode: proportional vertical scrubber mapped to timeline/scroll progress. */
function MotionScrubRail({
  doc,
  progress,
  onProgress,
}: {
  doc: PageDocumentV3;
  progress: number;
  onProgress: (p: number) => void;
}) {
  const trackRef = useRef<HTMLDivElement>(null);
  const sections = doc.pages ?? [];
  const weights = sections.map((s) => {
    const minH = s.settings?.minHeight;
    const n = typeof minH === "string" ? parseFloat(minH) : typeof minH === "number" ? minH : 480;
    return Math.max(120, Number.isFinite(n) ? n : 480);
  });
  const total = weights.reduce((a, b) => a + b, 0) || 1;

  const setFromClientY = (clientY: number) => {
    const el = trackRef.current;
    if (!el) return;
    const rect = el.getBoundingClientRect();
    const y = Math.max(0, Math.min(rect.height, clientY - rect.top));
    onProgress(rect.height > 0 ? y / rect.height : 0);
  };

  return (
    <div className="fk-section-rail-list fk-motion-scrub-rail">
      <div
        ref={trackRef}
        className="fk-motion-scrub-track"
        role="slider"
        aria-label="Scroll timeline"
        aria-valuemin={0}
        aria-valuemax={100}
        aria-valuenow={Math.round(progress * 100)}
        tabIndex={0}
        onPointerDown={(e) => {
          (e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);
          setFromClientY(e.clientY);
        }}
        onPointerMove={(e) => {
          if (e.buttons !== 1) return;
          setFromClientY(e.clientY);
        }}
        onKeyDown={(e) => {
          if (e.key === "ArrowDown" || e.key === "ArrowRight") {
            e.preventDefault();
            onProgress(Math.min(1, progress + 0.02));
          } else if (e.key === "ArrowUp" || e.key === "ArrowLeft") {
            e.preventDefault();
            onProgress(Math.max(0, progress - 0.02));
          }
        }}
      >
        {sections.map((sec, i) => (
          <div
            key={sec.id}
            className="fk-motion-scrub-band"
            style={{ flex: `${weights[i]! / total} 1 0` }}
          >
            <span className="fk-motion-scrub-band-label">S{i + 1}</span>
          </div>
        ))}
        <div className="fk-motion-scrub-playhead" style={{ top: `${progress * 100}%` }} />
      </div>
      <p className="fk-muted" style={{ fontSize: 10, padding: "8px 4px", margin: 0 }}>
        Drag to scrub scroll · {Math.round(progress * 100)}%
      </p>
    </div>
  );
}

export function SectionRail({
  doc,
  activeSectionId,
  onSelect,
  onAddSection,
  mode = "edit",
  scrubProgress = 0,
  onScrubProgress,
}: {
  doc: PageDocumentV3;
  activeSectionId: string | null;
  onSelect: (sectionId: string) => void;
  onAddSection?: (beforeIndex?: number) => void;
  mode?: "edit" | "motion";
  scrubProgress?: number;
  onScrubProgress?: (p: number) => void;
}) {
  const sections = doc.pages ?? [];

  return (
    <aside className="fk-section-rail" aria-label={mode === "motion" ? "Scroll scrubber" : "Sections"}>
      <div className="fk-section-rail-head">
        <span className="fk-eyebrow">{mode === "motion" ? "Scrub" : "Sections"}</span>
      </div>

      {mode === "motion" && onScrubProgress ? (
        <MotionScrubRail doc={doc} progress={scrubProgress} onProgress={onScrubProgress} />
      ) : (
        <>
          <div className="fk-section-rail-list">
            {sections.map((sec, i) => (
              <div key={sec.id}>
                {onAddSection && i === 0 ? null : null}
                <SectionThumb
                  section={sec}
                  index={i}
                  selected={sec.id === activeSectionId}
                  backgroundOverride={doc.pageBackgroundOverrides?.[sec.id]}
                  surfaceDefaults={doc.templateSurfaceDefaults}
                  animationDefaults={doc.templateAnimationDefaults}
                  onClick={() => onSelect(sec.id)}
                />
                {onAddSection ? (
                  <button
                    type="button"
                    className="fk-section-insert-between"
                    onClick={() => onAddSection(i + 1)}
                    title="Add section below"
                  >
                    <Plus size={12} /> Add
                  </button>
                ) : null}
              </div>
            ))}
          </div>
          {onAddSection ? (
            <div className="fk-section-rail-foot">
              <Button
                variant="quiet"
                size="sm"
                onClick={() => onAddSection(sections.length)}
                style={{ width: "100%" }}
              >
                <Plus size={14} /> Section
              </Button>
            </div>
          ) : null}
        </>
      )}
    </aside>
  );
}
