import { useEffect, useState } from "react";
import { Loader2 } from "lucide-react";

import { api, type PublicSitePayload } from "./api";
import { extractPageDocumentV3, type NavbarSettings } from "./document";
import { PublicSiteView } from "./PublicSiteView";
import { EditApp } from "./EditApp";
import { LoginForm, SetupForm } from "./AuthScreens";

function pathInfo() {
  const raw = location.pathname.replace(/\/+$/, "") || "/";
  if (raw === "/edit" || raw.startsWith("/edit/")) return { mode: "edit" as const, slug: "home" };
  if (raw === "/") return { mode: "public" as const, slug: "home" };
  return { mode: "public" as const, slug: raw.replace(/^\//, "") };
}

export function App() {
  const info = pathInfo();
  const [boot, setBoot] = useState<"loading" | "ready">("loading");
  const [configured, setConfigured] = useState(false);
  const [authed, setAuthed] = useState(false);
  const [publicData, setPublicData] = useState<PublicSitePayload | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    void (async () => {
      try {
        const status = await api<{ configured: boolean }>("/api/setup/status");
        setConfigured(status.configured);

        if (info.mode === "edit") {
          if (!status.configured) {
            setBoot("ready");
            return;
          }
          const me = await api<{ authenticated: boolean }>("/api/auth/me");
          setAuthed(me.authenticated);
          setBoot("ready");
          return;
        }

        if (!status.configured) {
          location.href = "/edit";
          return;
        }

        const data = await api<PublicSitePayload>(
          `/api/public/${encodeURIComponent(info.slug)}/data`
        );
        setPublicData(data);
        document.title =
          data.pageMeta?.documentTitle ||
          data.pages.find((p) => p.slug === data.currentSlug)?.title ||
          "Site";
        setBoot("ready");
      } catch (e) {
        const err = e as Error & { status?: number };
        if (err.status === 404 && info.mode === "public") {
          setError("Page not found");
        } else {
          setError(err.message || "Failed to load");
        }
        setBoot("ready");
      }
    })();
  }, [info.mode, info.slug]);

  if (boot === "loading") {
    return (
      <div className="fk-auth-wrap">
        <p className="fk-muted fk-row">
          <Loader2 size={16} className="animate-spin" /> Loading…
        </p>
      </div>
    );
  }

  if (info.mode === "edit") {
    if (!configured) return <SetupForm />;
    if (!authed) return <LoginForm />;
    return <EditApp />;
  }

  if (error || !publicData) {
    return (
      <div className="fk-auth-wrap">
        <div className="fk-auth-card">
          <p className="fk-eyebrow">Finnsk</p>
          <h1 className="fk-title" style={{ marginTop: 10 }}>
            Not found
          </h1>
          <p className="fk-muted" style={{ marginTop: 8 }}>
            {error || "Missing page"}
          </p>
          <a href="/" style={{ display: "inline-block", marginTop: 16 }}>
            Home
          </a>
        </div>
      </div>
    );
  }

  const doc = extractPageDocumentV3(publicData.blocks);
  if (!doc) {
    return (
      <div className="fk-auth-wrap">
        <div className="fk-auth-card">
          <h1 className="fk-title">Empty page</h1>
          <p className="fk-muted" style={{ marginTop: 8 }}>
            No document yet.
          </p>
          <a href="/edit" style={{ display: "inline-block", marginTop: 16 }}>
            Open admin
          </a>
        </div>
      </div>
    );
  }

  const navbar =
    publicData.settings?.navbar && typeof publicData.settings.navbar === "object"
      ? (publicData.settings.navbar as NavbarSettings)
      : null;

  return (
    <PublicSiteView
      doc={doc}
      pages={publicData.pages}
      currentSlug={publicData.currentSlug}
      navbar={navbar}
    />
  );
}
