import type { ReactNode } from "react";
import { FileText, Globe, LayoutTemplate, LogOut, Puzzle, Settings2 } from "lucide-react";

export type AdminSection = "pages" | "design" | "domain" | "integrations";

const NAV: Array<{ id: AdminSection; label: string; icon: typeof FileText }> = [
  { id: "pages", label: "Pages", icon: FileText },
  { id: "design", label: "Design", icon: LayoutTemplate },
  { id: "domain", label: "Domain", icon: Globe },
  { id: "integrations", label: "Integrations", icon: Puzzle },
];

export function AdminShell({
  section,
  onSection,
  siteName,
  bar,
  children,
  onLogout,
}: {
  section: AdminSection;
  onSection: (s: AdminSection) => void;
  siteName: string;
  bar?: ReactNode;
  children: ReactNode;
  onLogout: () => void;
}) {
  return (
    <div className="fk-shell">
      <aside className="fk-sidebar">
        <div className="fk-sidebar-brand">
          <span className="fk-eyebrow">Finnsk</span>
          <strong style={{ fontSize: 15, fontWeight: 600 }}>{siteName || "My Site"}</strong>
          <span className="fk-muted" style={{ fontSize: 12 }}>
            Website admin
          </span>
        </div>
        <nav className="fk-sidebar-nav" aria-label="Admin">
          {NAV.map((item) => {
            const Icon = item.icon;
            const active = section === item.id;
            return (
              <button
                key={item.id}
                type="button"
                className={`fk-nav-item${active ? " is-active" : ""}`}
                aria-current={active ? "page" : undefined}
                onClick={() => onSection(item.id)}
              >
                <Icon size={16} strokeWidth={1.75} />
                {item.label}
              </button>
            );
          })}
        </nav>
        <div className="fk-sidebar-foot">
          <a className="fk-nav-item" href="/" target="_blank" rel="noreferrer">
            <Globe size={16} strokeWidth={1.75} />
            View live site
          </a>
          <button type="button" className="fk-nav-item" onClick={onLogout}>
            <LogOut size={16} strokeWidth={1.75} />
            Sign out
          </button>
        </div>
      </aside>
      <div className="fk-main">
        <header className="fk-main-bar">
          <Settings2 size={16} color="var(--fk-orange)" strokeWidth={1.75} />
          <span className="fk-eyebrow" style={{ marginRight: 4 }}>
            {NAV.find((n) => n.id === section)?.label}
          </span>
          <div style={{ flex: 1 }} />
          {bar}
        </header>
        <div className="fk-main-body">{children}</div>
      </div>
    </div>
  );
}

export function SectionHeader({
  title,
  description,
  actions,
}: {
  title: string;
  description?: string;
  actions?: ReactNode;
}) {
  return (
    <div
      className="fk-row"
      style={{
        justifyContent: "space-between",
        padding: "20px 20px 12px",
        borderBottom: "1px solid var(--border)",
      }}
    >
      <div>
        <h1 className="fk-title" style={{ fontSize: "1.25rem" }}>
          {title}
        </h1>
        {description ? (
          <p className="fk-muted" style={{ margin: "6px 0 0", maxWidth: 520 }}>
            {description}
          </p>
        ) : null}
      </div>
      {actions}
    </div>
  );
}
