import { useEffect, useRef, useState } from "react";
import {
  ProposalBrandingPreviewProvider,
  ProposalDocument,
  SiteCanvasPreviewProvider,
} from "@proposalengine/proposal-builder";
import type { PageDocumentV3 } from "@proposalengine/proposal-builder/document";
import {
  Check,
  ChevronDown,
  Loader2,
  Maximize2,
  Minimize2,
  Sparkles,
  Upload,
  X,
} from "lucide-react";
import { Button, Textarea } from "./ui";

export type AgentChatMsg = {
  id: string;
  role: "user" | "assistant" | "system";
  text: string;
};

export type AgentToolChip = {
  name: string;
  args?: unknown;
  resultSummary?: string;
};

export type AgentPendingPlan = {
  pageSlug: string;
  summary: string;
  ops: unknown[];
  preview: {
    ok: boolean;
    errors: string[];
    summaries: string[];
    diffSummary: string;
  };
  previewDocument?: unknown;
};

export type AgentAssetRequest = {
  reason: string;
  accept?: string;
  purpose?: string;
};

type AgentHistoryItem = {
  role: "user" | "model" | "tool";
  text?: string;
  toolName?: string;
  toolArgs?: unknown;
  toolResult?: unknown;
};

type PersistedAgentState = {
  open: boolean;
  expanded: boolean;
  messages: AgentChatMsg[];
  history: AgentHistoryItem[];
  toolCalls: AgentToolChip[];
  pendingPlan: AgentPendingPlan | null;
  assetRequest: AgentAssetRequest | null;
  status: string | null;
};

const STORAGE_KEY = "finnsk-solo-agent-v1";

const DEFAULT_BRANDING = {
  primaryColor: "#ea580c",
  accentColor: "#ea580c",
  fontFamilyHeading: "IBM Plex Sans, sans-serif",
  fontFamilyBody: "IBM Plex Sans, sans-serif",
};

function loadState(): PersistedAgentState {
  try {
    const raw = sessionStorage.getItem(STORAGE_KEY);
    if (!raw) throw new Error("empty");
    return JSON.parse(raw) as PersistedAgentState;
  } catch {
    return {
      open: false,
      expanded: true,
      messages: [
        {
          id: "welcome",
          role: "system",
          text: "Design Agent — stays with you while you browse. Ask it to build pages; Approve plans when ready.",
        },
      ],
      history: [],
      toolCalls: [],
      pendingPlan: null,
      assetRequest: null,
      status: null,
    };
  }
}

export function AgentDock({
  pageSlug,
  selection,
  onNavigatePage,
  onDocumentApplied,
  onOpenPageEditor,
}: {
  pageSlug: string;
  selection: { sectionId: string; blockId: string | null } | null;
  onNavigatePage: (slug: string) => void;
  onDocumentApplied: (slug: string, document: unknown) => void;
  /** Open canvas editor for a page (e.g. after Approve). */
  onOpenPageEditor?: (slug: string) => void;
}) {
  const [open, setOpen] = useState(() => loadState().open);
  const [expanded, setExpanded] = useState(() => loadState().expanded);
  const [input, setInput] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [status, setStatus] = useState<string | null>(() => loadState().status);
  const [messages, setMessages] = useState<AgentChatMsg[]>(() => loadState().messages);
  const [history, setHistory] = useState<AgentHistoryItem[]>(() => loadState().history);
  const [toolCalls, setToolCalls] = useState<AgentToolChip[]>(() => loadState().toolCalls);
  const [pendingPlan, setPendingPlan] = useState<AgentPendingPlan | null>(
    () => loadState().pendingPlan
  );
  const [assetRequest, setAssetRequest] = useState<AgentAssetRequest | null>(
    () => loadState().assetRequest
  );
  const [applyMsg, setApplyMsg] = useState<string | null>(null);
  const [canRetry, setCanRetry] = useState(false);
  const fileRef = useRef<HTMLInputElement>(null);
  const historyRef = useRef(history);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    historyRef.current = history;
  }, [history]);

  useEffect(() => {
    const payload: PersistedAgentState = {
      open,
      expanded,
      messages,
      history,
      toolCalls,
      pendingPlan,
      assetRequest,
      status,
    };
    try {
      sessionStorage.setItem(STORAGE_KEY, JSON.stringify(payload));
    } catch {
      /* quota */
    }
  }, [open, expanded, messages, history, toolCalls, pendingPlan, assetRequest, status]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages, toolCalls, status, pendingPlan]);

  const pushMsg = (role: AgentChatMsg["role"], text: string) => {
    setMessages((prev) => [...prev, { id: crypto.randomUUID(), role, text }]);
  };

  const runTurn = async (
    message: string,
    uploadedMedia?: { mediaId: string; filename?: string },
    opts?: { clearTools?: boolean }
  ) => {
    setBusy(true);
    setError(null);
    setCanRetry(false);
    setApplyMsg(null);
    setStatus("Connecting…");
    setOpen(true);
    setExpanded(true);
    if (opts?.clearTools !== false) {
      // keep tools when continuing after a 503
    }
    try {
      const res = await fetch("/api/ai/agent", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Accept: "text/event-stream",
        },
        credentials: "include",
        body: JSON.stringify({
          message,
          history: historyRef.current,
          pageSlug,
          selection,
          uploadedMedia: uploadedMedia || null,
          stream: true,
        }),
      });

      if (!res.ok) {
        const data = (await res.json().catch(() => ({}))) as { error?: string };
        throw new Error(data.error || "Agent failed");
      }

      const reader = res.body?.getReader();
      if (!reader) throw new Error("No stream");
      const decoder = new TextDecoder();
      let buffer = "";
      let sawError = false;

      while (true) {
        const { done, value } = await reader.read();
        if (done) break;
        buffer += decoder.decode(value, { stream: true });
        const chunks = buffer.split("\n\n");
        buffer = chunks.pop() || "";
        for (const chunk of chunks) {
          const line = chunk
            .split("\n")
            .find((l) => l.startsWith("data: "));
          if (!line) continue;
          let ev: {
            type: string;
            message?: string;
            name?: string;
            args?: unknown;
            resultSummary?: string;
            phase?: string;
            role?: string;
            text?: string;
            plan?: AgentPendingPlan;
            pageSlug?: string;
            request?: AgentAssetRequest;
            reply?: string;
            toolCalls?: AgentToolChip[];
            pendingPlan?: AgentPendingPlan | null;
            assetRequest?: AgentAssetRequest | null;
            navigate?: { pageSlug: string } | null;
            history?: AgentHistoryItem[];
          };
          try {
            ev = JSON.parse(line.slice(6));
          } catch {
            continue;
          }

          if (ev.type === "status") setStatus(ev.message || null);
          if (ev.type === "error") {
            sawError = true;
            setError(ev.message || "Error");
            setCanRetry(true);
          }
          if (ev.type === "message" && ev.text) {
            pushMsg(ev.role === "system" ? "system" : "assistant", ev.text);
          }
          if (ev.type === "tool") {
            if (ev.phase === "start") {
              setStatus(`Running ${ev.name}…`);
              setToolCalls((prev) => [
                ...prev,
                { name: String(ev.name), args: ev.args, resultSummary: "…" },
              ]);
            } else {
              setToolCalls((prev) => {
                const next = [...prev];
                for (let i = next.length - 1; i >= 0; i--) {
                  if (next[i].name === ev.name && next[i].resultSummary === "…") {
                    next[i] = {
                      name: String(ev.name),
                      args: ev.args,
                      resultSummary: ev.resultSummary,
                    };
                    break;
                  }
                }
                return next;
              });
            }
          }
          if (ev.type === "plan" && ev.plan) {
            setPendingPlan(ev.plan);
            setStatus("Plan ready — Approve to apply");
            setCanRetry(false);
          }
          if (ev.type === "asset" && ev.request) setAssetRequest(ev.request);
          if (ev.type === "navigate" && ev.pageSlug) {
            onNavigatePage(ev.pageSlug);
          }
          if (ev.type === "done") {
            if (ev.history) setHistory(ev.history);
            if (ev.toolCalls?.length) setToolCalls(ev.toolCalls);
            setPendingPlan(ev.pendingPlan || null);
            setAssetRequest(ev.assetRequest || null);
            if (ev.navigate?.pageSlug) onNavigatePage(ev.navigate.pageSlug);
            if (ev.reply && !sawError) {
              setMessages((prev) => {
                const last = prev[prev.length - 1];
                if (last?.role === "assistant" && last.text === ev.reply) return prev;
                return [
                  ...prev,
                  { id: crypto.randomUUID(), role: "assistant", text: ev.reply! },
                ];
              });
            }
            if (sawError || (ev.reply && /Gemini error|overloaded|503|429/i.test(ev.reply))) {
              setCanRetry(true);
              setError(ev.reply || error || "Gemini busy");
            }
            setStatus(ev.pendingPlan ? "Awaiting Approve" : sawError ? "Paused — Retry" : null);
          }
        }
      }
    } catch (e) {
      setError(e instanceof Error ? e.message : "Agent failed");
      setCanRetry(true);
      setStatus(null);
    } finally {
      setBusy(false);
    }
  };

  const send = async () => {
    const text = input.trim();
    if (!text || busy) return;
    setInput("");
    setToolCalls([]);
    pushMsg("user", text);
    await runTurn(text);
  };

  const retryContinue = async () => {
    if (busy) return;
    pushMsg(
      "user",
      "Continue from where you left off. You already have tool results — call propose_ops now with the full plan (Scene3D room + floating icons + scroll motion). Do not re-list capabilities."
    );
    await runTurn(
      "Continue now: propose_ops with the 3D room page (floating objects, scroll spin/scale toward viewer, click/hover reveal text). Skip research tools you already ran.",
      undefined,
      { clearTools: false }
    );
  };

  const approve = async () => {
    if (!pendingPlan || !pendingPlan.preview.ok) return;
    setBusy(true);
    setError(null);
    try {
      const res = await fetch("/api/ops/apply", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify({
          pageSlug: pendingPlan.pageSlug,
          ops: pendingPlan.ops,
        }),
      });
      const data = (await res.json()) as {
        error?: string;
        document?: unknown;
        summaries?: string[];
      };
      if (!res.ok) throw new Error(data.error || "Apply failed");
      setApplyMsg(data.summaries?.join("; ") || "Applied");
      onDocumentApplied(pendingPlan.pageSlug, data.document);
      pushMsg("system", `Applied on /${pendingPlan.pageSlug}`);
      const slug = pendingPlan.pageSlug;
      setPendingPlan(null);
      setStatus(null);
      onNavigatePage(slug);
      onOpenPageEditor?.(slug);
    } catch (e) {
      setError(e instanceof Error ? e.message : "Apply failed");
    } finally {
      setBusy(false);
    }
  };

  const reject = () => {
    setPendingPlan(null);
    setStatus(null);
    pushMsg("system", "Plan rejected.");
  };

  const onUpload = async (file: File) => {
    setBusy(true);
    setError(null);
    try {
      const fd = new FormData();
      fd.append("file", file);
      const res = await fetch("/api/media", {
        method: "POST",
        credentials: "include",
        body: fd,
      });
      const data = (await res.json()) as {
        error?: string;
        media?: { id?: string; mediaId?: string; filename?: string };
      };
      if (!res.ok) throw new Error(data.error || "Upload failed");
      const mediaId = data.media?.mediaId || data.media?.id;
      if (!mediaId) throw new Error("No mediaId returned");
      setAssetRequest(null);
      pushMsg("user", `Uploaded ${file.name}`);
      await runTurn("Asset uploaded — continue.", {
        mediaId,
        filename: data.media?.filename || file.name,
      });
    } catch (e) {
      setError(e instanceof Error ? e.message : "Upload failed");
      setBusy(false);
    }
  };

  const previewDoc = pendingPlan?.previewDocument as PageDocumentV3 | undefined;

  return (
    <div className="fk-agent-dock" aria-live="polite">
      {!open ? (
        <button
          type="button"
          className="fk-agent-fab"
          onClick={() => {
            setOpen(true);
            setExpanded(true);
          }}
          title="Design Agent"
        >
          <Sparkles size={18} strokeWidth={1.75} />
          {pendingPlan ? <span className="fk-agent-fab-dot" /> : null}
        </button>
      ) : (
        <div className={`fk-agent-float${expanded ? " is-expanded" : ""}`}>
          <header className="fk-agent-float-bar">
            <Sparkles size={14} color="var(--fk-orange)" strokeWidth={1.75} />
            <strong>Agent</strong>
            <span className="fk-muted" style={{ fontSize: 11 }}>
              /{pageSlug}
            </span>
            <div style={{ flex: 1 }} />
            <button
              type="button"
              className="fk-agent-icon-btn"
              onClick={() => setExpanded((v) => !v)}
              aria-label={expanded ? "Collapse" : "Expand"}
            >
              {expanded ? <Minimize2 size={14} /> : <Maximize2 size={14} />}
            </button>
            <button
              type="button"
              className="fk-agent-icon-btn"
              onClick={() => setOpen(false)}
              aria-label="Close"
            >
              <ChevronDown size={14} />
            </button>
          </header>

          {expanded ? (
            <div className="fk-agent-float-body">
              {status ? (
                <div className="fk-agent-status">
                  {busy ? <Loader2 size={12} className="fk-spin" /> : null}
                  {status}
                </div>
              ) : null}

              <div className="fk-agent-float-messages">
                {messages.map((m) => (
                  <div key={m.id} className={`fk-agent-msg is-${m.role}`}>
                    {m.text}
                  </div>
                ))}
                <div ref={messagesEndRef} />
              </div>

              {toolCalls.length ? (
                <div className="fk-agent-chips">
                  {toolCalls.map((t, i) => (
                    <button
                      key={`${t.name}-${i}`}
                      type="button"
                      className="fk-agent-chip"
                      title={t.resultSummary}
                      onClick={() => {
                        const slug =
                          pendingPlan?.pageSlug ||
                          (typeof t.args === "object" &&
                          t.args &&
                          "pageSlug" in t.args
                            ? String((t.args as { pageSlug?: string }).pageSlug)
                            : null);
                        if (slug) {
                          onNavigatePage(slug);
                          onOpenPageEditor?.(slug);
                        }
                      }}
                    >
                      {t.name}
                    </button>
                  ))}
                </div>
              ) : null}

              {assetRequest ? (
                <div className="fk-agent-plan-card">
                  <strong>Asset needed</strong>
                  <p className="fk-muted" style={{ margin: "6px 0", fontSize: 12 }}>
                    {assetRequest.reason}
                  </p>
                  <input
                    ref={fileRef}
                    type="file"
                    accept={assetRequest.accept || "image/*,.glb,.gltf"}
                    hidden
                    onChange={(e) => {
                      const f = e.target.files?.[0];
                      if (f) void onUpload(f);
                      e.target.value = "";
                    }}
                  />
                  <Button size="sm" disabled={busy} onClick={() => fileRef.current?.click()}>
                    <Upload size={14} /> Upload
                  </Button>
                </div>
              ) : null}

              {pendingPlan ? (
                <div className="fk-agent-plan-card">
                  <button
                    type="button"
                    className="fk-agent-plan-jump"
                    onClick={() => {
                      onNavigatePage(pendingPlan.pageSlug);
                      onOpenPageEditor?.(pendingPlan.pageSlug);
                    }}
                  >
                    <strong>{pendingPlan.summary}</strong>
                    <span className="fk-muted">
                      /{pendingPlan.pageSlug} · {pendingPlan.ops.length} ops ·{" "}
                      {pendingPlan.preview.diffSummary}
                    </span>
                  </button>
                  {!pendingPlan.preview.ok ? (
                    <p style={{ color: "var(--fk-danger)", fontSize: 12, margin: "6px 0" }}>
                      {pendingPlan.preview.errors.join("; ")}
                    </p>
                  ) : null}
                  {previewDoc?.pages ? (
                    <div className="fk-agent-preview">
                      <ProposalBrandingPreviewProvider value={DEFAULT_BRANDING}>
                        <SiteCanvasPreviewProvider>
                          <div className="fk-agent-preview-scale">
                            <ProposalDocument
                              sections={previewDoc.pages}
                              sectionBackgroundOverrides={previewDoc.pageBackgroundOverrides}
                              proposalSurfaceDefaults={previewDoc.templateSurfaceDefaults}
                              proposalAnimationDefaults={previewDoc.templateAnimationDefaults}
                              timelines={previewDoc.timelines}
                              previewInteractive={false}
                              layoutMode="website"
                            />
                          </div>
                        </SiteCanvasPreviewProvider>
                      </ProposalBrandingPreviewProvider>
                    </div>
                  ) : null}
                  <div className="fk-row" style={{ gap: 8, marginTop: 8 }}>
                    <Button
                      size="sm"
                      disabled={busy || !pendingPlan.preview.ok}
                      onClick={() => void approve()}
                    >
                      <Check size={14} /> Approve
                    </Button>
                    <Button size="sm" variant="ghost" disabled={busy} onClick={reject}>
                      <X size={14} /> Reject
                    </Button>
                  </div>
                </div>
              ) : null}

              {error ? (
                <div className="fk-agent-error">
                  <p style={{ color: "var(--fk-danger)", fontSize: 12, margin: 0, whiteSpace: "pre-wrap" }}>
                    {error}
                  </p>
                  {canRetry ? (
                    <Button size="sm" disabled={busy} onClick={() => void retryContinue()}>
                      {busy ? <Loader2 size={14} className="fk-spin" /> : null}
                      Retry continue
                    </Button>
                  ) : null}
                </div>
              ) : null}
              {applyMsg ? (
                <p className="fk-muted" style={{ fontSize: 12, margin: 0 }}>
                  {applyMsg}
                </p>
              ) : null}

              <div className="fk-agent-float-composer">
                <Textarea
                  rows={2}
                  value={input}
                  disabled={busy}
                  placeholder="Build a page, add icons, Scene3D…"
                  onChange={(e) => setInput(e.target.value)}
                  onKeyDown={(e) => {
                    if (e.key === "Enter" && (e.metaKey || e.ctrlKey)) void send();
                  }}
                />
                <Button size="sm" disabled={busy || !input.trim()} onClick={() => void send()}>
                  {busy ? <Loader2 size={14} className="fk-spin" /> : <Sparkles size={14} />}
                  Send
                </Button>
              </div>
            </div>
          ) : null}
        </div>
      )}
    </div>
  );
}
