import { useCallback, useEffect, useMemo, useState } from "react";
import {
  MotionRuntimeProvider,
  ProposalDocument,
  ProposalBrandingPreviewProvider,
  SiteCanvasPreviewProvider,
} from "@proposalengine/proposal-builder";
import type {
  MotionLink,
  PageDocumentV3,
  PageV2,
} from "@proposalengine/proposal-builder/document";
import { createBlankProposalPage } from "@proposalengine/proposal-builder/document";
import {
  ArrowLeft,
  Eye,
  FileText,
  Loader2,
  Pencil,
  Plus,
  Save,
  Sparkles,
  Trash2,
} from "lucide-react";

import { api, type PageRow } from "./api";
import {
  DEFAULT_NAVBAR,
  fromEditorPage,
  toEditorPage,
  type NavbarSettings,
} from "./document";
import { AdminShell, type AdminSection, SectionHeader } from "./AdminShell";
import { AgentDock } from "./AgentPanel";
import { Button, Field, Input, Panel, Textarea } from "./ui";
import { TimelineSheet } from "./TimelinePanel";
import { SectionRail } from "./SectionRail";
import { MotionRightRail, type MotionBlockRef } from "./MotionRightRail";

const DEFAULT_BRANDING = {
  primaryColor: "#ea580c",
  accentColor: "#ea580c",
  fontFamilyHeading: "IBM Plex Sans, sans-serif",
  fontFamilyBody: "IBM Plex Sans, sans-serif",
};

type ComposeSel = { sectionId: string; blockId: string | null } | null;
/** null = browse pages in admin shell; edit/preview = fullscreen studio */
type StudioMode = null | "edit" | "preview";

export function EditApp() {
  const [section, setSection] = useState<AdminSection>("pages");
  const [studioMode, setStudioMode] = useState<StudioMode>(null);
  const [pages, setPages] = useState<PageRow[]>([]);
  const [slug, setSlug] = useState("home");
  const [doc, setDoc] = useState<PageDocumentV3 | null>(null);
  const [dirty, setDirty] = useState(false);
  const [saving, setSaving] = useState(false);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [settings, setSettings] = useState<Record<string, unknown>>({});
  const [siteName, setSiteName] = useState("My Site");
  const [navDraft, setNavDraft] = useState<NavbarSettings>({ ...DEFAULT_NAVBAR });
  const [domainDraft, setDomainDraft] = useState("");
  const [domainMsg, setDomainMsg] = useState<string | null>(null);
  const [designMsg, setDesignMsg] = useState<string | null>(null);
  const [surfacePreset, setSurfacePreset] = useState<
    "transparent" | "transparent_shadow" | "glass" | "solid"
  >("transparent");
  const [aiKeyDraft, setAiKeyDraft] = useState("");
  const [aiModelDraft, setAiModelDraft] = useState("gemini-2.5-flash");
  const [aiKeySet, setAiKeySet] = useState(false);
  const [mcpToken, setMcpToken] = useState<string | null>(null);
  const [aiMsg, setAiMsg] = useState<string | null>(null);
  const [selection, setSelection] = useState<ComposeSel>(null);
  const [activeSectionId, setActiveSectionId] = useState<string | null>(null);
  const [seoTitle, setSeoTitle] = useState("");
  const [seoDesc, setSeoDesc] = useState("");
  const [pageMetaOpen, setPageMetaOpen] = useState(false);
  const [motionOpen, setMotionOpen] = useState(false);
  const [motionProgress, setMotionProgress] = useState(0);
  const [activeTimelineId, setActiveTimelineId] = useState<string | null>(null);
  const [motionBlocks, setMotionBlocks] = useState<MotionBlockRef[]>([]);

  const loadPages = useCallback(async () => {
    const data = await api<{ pages: PageRow[] }>("/api/pages");
    setPages(data.pages);
    return data.pages;
  }, []);

  const loadDoc = useCallback(async (pageSlug: string) => {
    setLoading(true);
    setError(null);
    try {
      const data = await api<{
        document: unknown;
        page: {
          title?: string;
          published?: number;
          seo?: { metaTitle?: string; metaDescription?: string };
        };
      }>(`/api/pages/${encodeURIComponent(pageSlug)}/document`);
      const next = data.document as PageDocumentV3;
      setDoc(next);
      setSlug(pageSlug);
      setDirty(false);
      setSelection(null);
      setActiveSectionId(next.pages?.[0]?.id ?? null);
      const surf = next.templateSurfaceDefaults?.preset;
      if (
        surf === "transparent" ||
        surf === "transparent_shadow" ||
        surf === "glass" ||
        surf === "solid"
      ) {
        setSurfacePreset(surf);
      }
      setSeoTitle(data.page?.seo?.metaTitle || "");
      setSeoDesc(data.page?.seo?.metaDescription || "");
    } catch (e) {
      setError(e instanceof Error ? e.message : "Failed to load");
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    void (async () => {
      try {
        const list = await loadPages();
        const first = list[0]?.slug || "home";
        await loadDoc(first);
        const s = await api<{ settings: Record<string, unknown> }>("/api/settings");
        setSettings(s.settings || {});
        const nav = {
          ...DEFAULT_NAVBAR,
          ...((s.settings?.navbar as NavbarSettings) || {}),
        };
        setNavDraft(nav);
        setSiteName(nav.brand || "My Site");
        const ai = (s.settings?.ai || {}) as {
          apiKeySet?: boolean;
          model?: string;
        };
        setAiKeySet(Boolean(ai.apiKeySet));
        if (ai.model) setAiModelDraft(ai.model);
        if (typeof s.settings?.mcpToken === "string") {
          setMcpToken(s.settings.mcpToken);
        }
        const domains = await api<{ domains: Array<{ hostname: string }> }>("/api/domains").catch(
          () => ({ domains: [] as Array<{ hostname: string }> })
        );
        if (domains.domains[0]?.hostname) setDomainDraft(domains.domains[0].hostname);
      } catch (e) {
        setError(e instanceof Error ? e.message : "Failed to load");
        setLoading(false);
      }
    })();
  }, [loadDoc, loadPages]);

  const handleDraftChange = useCallback((next: PageV2) => {
    setDoc((prev) => {
      const merged = fromEditorPage(next, prev);
      if (prev && JSON.stringify(prev) === JSON.stringify(merged)) return prev;
      return merged;
    });
    setDirty(true);
  }, []);

  const handleDocChange = useCallback((next: PageDocumentV3) => {
    setDoc((prev) => (prev && JSON.stringify(prev) === JSON.stringify(next) ? prev : next));
    setDirty(true);
  }, []);

  const onComposeSelectionChange = useCallback((sel: ComposeSel) => {
    setSelection((prev) => {
      if (prev?.sectionId === sel?.sectionId && prev?.blockId === sel?.blockId) return prev;
      return sel;
    });
    if (sel?.sectionId) {
      setActiveSectionId((prev) => (prev === sel.sectionId ? prev : sel.sectionId));
    }
  }, []);

  const uploadTemplateImage = useCallback(async (file: File) => {
    const fd = new FormData();
    fd.append("file", file);
    const res = await fetch("/api/media", {
      method: "POST",
      credentials: "include",
      body: fd,
    });
    if (!res.ok) throw new Error("Upload failed");
    const data = (await res.json()) as {
      media: { url: string; mediaKey: string; mediaId: string };
    };
    return {
      src: data.media.url,
      mediaKey: data.media.mediaKey,
      mediaId: data.media.mediaId,
    };
  }, []);

  const onComposeMultiSelectionChange = useCallback(
    (blocks: Array<{ sectionId: string; blockId: string }>) => {
      setMotionBlocks(blocks);
    },
    []
  );

  const proposalStudio = useMemo(
    () => ({
      userLoginsResponse: null,
      resolveCatalogEntryId: () => "",
      onComposeSelectionChange,
      onComposeMultiSelectionChange,
      openInspectorOnBlockSelect: true as const,
      uploadTemplateImage,
    }),
    [onComposeSelectionChange, onComposeMultiSelectionChange, uploadTemplateImage]
  );

  useEffect(() => {
    if (!doc?.timelines?.length) {
      setActiveTimelineId(null);
      return;
    }
    if (!activeTimelineId || !doc.timelines.some((t) => t.id === activeTimelineId)) {
      setActiveTimelineId(doc.timelines[0]!.id);
    }
  }, [doc?.timelines, activeTimelineId]);

  const toggleMotionBlock = (ref: MotionBlockRef, additive: boolean) => {
    setMotionBlocks((prev) => {
      if (additive) {
        if (prev.some((b) => b.blockId === ref.blockId)) {
          return prev.filter((b) => b.blockId !== ref.blockId);
        }
        return [...prev, ref];
      }
      return [ref];
    });
    setSelection({ sectionId: ref.sectionId, blockId: ref.blockId });
    setActiveSectionId(ref.sectionId);
  };

  const createTimeline = () => {
    if (!doc) return;
    const id = `tl-${crypto.randomUUID().slice(0, 8)}`;
    const next = {
      ...doc,
      timelines: [
        ...(doc.timelines ?? []),
        {
          id,
          name: `Timeline ${(doc.timelines?.length ?? 0) + 1}`,
          duration: 1,
          scrub: true,
          tracks: [],
        },
      ],
    };
    setDoc(next);
    setDirty(true);
    setActiveTimelineId(id);
  };

  const addGroupToTimeline = (channel: string = "opacity") => {
    if (!doc || motionBlocks.length === 0) return;
    let timelines = [...(doc.timelines ?? [])];
    let tlId = activeTimelineId;
    if (!tlId || !timelines.some((t) => t.id === tlId)) {
      tlId = `tl-${crypto.randomUUID().slice(0, 8)}`;
      timelines.push({
        id: tlId,
        name: `Timeline ${timelines.length + 1}`,
        duration: 1,
        scrub: true,
        tracks: [],
      });
      setActiveTimelineId(tlId);
    }
    timelines = timelines.map((tl) => {
      if (tl.id !== tlId) return tl;
      const tracks = [...(tl.tracks ?? [])];
      motionBlocks.forEach((ref, i) => {
        const stagger = motionBlocks.length > 1 ? i / motionBlocks.length : 0;
        tracks.push({
          id: `tr-${crypto.randomUUID().slice(0, 6)}`,
          blockId: ref.blockId,
          channel: channel as "opacity" | "y",
          keyframes: [
            {
              t: stagger * 0.35,
              value: channel === "opacity" ? 0 : 48,
            },
            {
              t: Math.min(1, 0.55 + stagger * 0.35),
              value: channel === "opacity" ? 1 : 0,
              easing: "power2.out",
            },
          ],
        });
      });
      return { ...tl, tracks };
    });
    setDoc({ ...doc, timelines });
    setDirty(true);
  };

  const save = async () => {
    if (!doc) return;
    setSaving(true);
    setError(null);
    try {
      await api(`/api/pages/${encodeURIComponent(slug)}/document`, {
        method: "PUT",
        body: JSON.stringify({ document: doc }),
      });
      setDirty(false);
    } catch (e) {
      setError(e instanceof Error ? e.message : "Save failed");
    } finally {
      setSaving(false);
    }
  };

  const addPage = async () => {
    const title = window.prompt("Page title?");
    if (!title?.trim()) return;
    const nextSlug = title
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/^-|-$/g, "");
    try {
      await api("/api/pages", {
        method: "POST",
        body: JSON.stringify({ slug: nextSlug, title: title.trim() }),
      });
      await loadPages();
      await loadDoc(nextSlug);
      setSection("pages");
      setStudioMode(null);
    } catch (e) {
      setError(e instanceof Error ? e.message : "Could not create page");
    }
  };

  const renamePage = async () => {
    const current = pages.find((p) => p.slug === slug);
    const title = window.prompt("Page title?", current?.title || slug);
    if (!title?.trim()) return;
    try {
      await api(`/api/pages/${encodeURIComponent(slug)}`, {
        method: "PATCH",
        body: JSON.stringify({ title: title.trim() }),
      });
      await loadPages();
    } catch (e) {
      setError(e instanceof Error ? e.message : "Rename failed");
    }
  };

  const togglePublished = async () => {
    const current = pages.find((p) => p.slug === slug);
    if (!current) return;
    try {
      await api(`/api/pages/${encodeURIComponent(slug)}`, {
        method: "PATCH",
        body: JSON.stringify({ published: !current.published }),
      });
      await loadPages();
    } catch (e) {
      setError(e instanceof Error ? e.message : "Publish toggle failed");
    }
  };

  const saveSeo = async () => {
    try {
      await api(`/api/pages/${encodeURIComponent(slug)}`, {
        method: "PATCH",
        body: JSON.stringify({
          seo_json: { metaTitle: seoTitle.trim(), metaDescription: seoDesc.trim() },
        }),
      });
      setPageMetaOpen(false);
    } catch (e) {
      setError(e instanceof Error ? e.message : "SEO save failed");
    }
  };

  const deletePage = async () => {
    if (slug === "home") return;
    if (!window.confirm(`Delete page “${slug}”?`)) return;
    try {
      await api(`/api/pages/${encodeURIComponent(slug)}`, { method: "DELETE" });
      const list = await loadPages();
      await loadDoc(list[0]?.slug || "home");
      setStudioMode(null);
    } catch (e) {
      setError(e instanceof Error ? e.message : "Delete failed");
    }
  };

  const saveDesign = async () => {
    setDesignMsg(null);
    const navbar = { ...navDraft, brand: (navDraft.brand || "My Site").trim() };
    const next = { ...settings, navbar };
    await api("/api/settings", { method: "PUT", body: JSON.stringify({ settings: next }) });
    setSettings(next);
    setSiteName(navbar.brand || "My Site");
    if (doc) {
      const withSurface: PageDocumentV3 = {
        ...doc,
        templateSurfaceDefaults: {
          ...(doc.templateSurfaceDefaults || {}),
          preset: surfacePreset,
          borderMode: surfacePreset === "transparent" ? "none" : doc.templateSurfaceDefaults?.borderMode,
        },
      };
      setDoc(withSurface);
      await api(`/api/pages/${encodeURIComponent(slug)}/document`, {
        method: "PUT",
        body: JSON.stringify({ document: withSurface }),
      });
      setDirty(false);
    }
    setDesignMsg("Saved.");
  };

  const applyCutoutChrome = () => {
    if (!doc || motionBlocks.length === 0) return;
    const ids = new Set(motionBlocks.map((b) => b.blockId));
    const pages = doc.pages.map((sec) => ({
      ...sec,
      blocks: (sec.blocks ?? []).map((b) => {
        if (!ids.has(b.id) || b.type !== "Image") return b;
        return {
          ...b,
          props: {
            ...(b.props || {}),
            chrome: "cutout",
            layout: "inline",
            shadow: "none",
            borderWidth: 0,
            borderColor: "",
            ring: 0,
            rounded: "none",
          },
        };
      }),
    }));
    setDoc({
      ...doc,
      pages,
      templateSurfaceDefaults: {
        ...(doc.templateSurfaceDefaults || {}),
        preset: "transparent",
        borderMode: "none",
      },
    });
    setSurfacePreset("transparent");
    setDirty(true);
  };

  const saveAi = async () => {
    setAiMsg(null);
    const ai: Record<string, unknown> = {
      provider: "gemini",
      model: aiModelDraft.trim() || "gemini-2.5-flash",
    };
    if (aiKeyDraft.trim()) ai.apiKey = aiKeyDraft.trim();
    const next = { ...settings, ai };
    await api("/api/settings", { method: "PUT", body: JSON.stringify({ settings: next }) });
    setSettings(next);
    if (aiKeyDraft.trim()) {
      setAiKeySet(true);
      setAiKeyDraft("");
    }
    setAiMsg("AI settings saved.");
  };

  const rotateMcpToken = async () => {
    const res = await api<{ mcpToken: string }>("/api/ai/token", {
      method: "POST",
      body: "{}",
    });
    setMcpToken(res.mcpToken);
    setSettings((s) => ({ ...s, mcpToken: res.mcpToken }));
    setAiMsg("New MCP token generated — copy it into Cursor now.");
  };

  const saveDomain = async () => {
    setDomainMsg(null);
    try {
      const res = await api<{
        instructions?: { steps?: string[] } | null;
      }>("/api/domains", {
        method: "PUT",
        body: JSON.stringify({ hostname: domainDraft.trim() }),
      });
      setDomainMsg(
        domainDraft.trim()
          ? (res.instructions?.steps?.join(" ") ??
              "Saved. Attach this hostname in Cloudflare Workers → Custom Domains.")
          : "Domain cleared."
      );
    } catch (e) {
      setDomainMsg(e instanceof Error ? e.message : "Domain save failed");
    }
  };

  const logout = () => {
    void api("/api/auth/logout", { method: "POST", body: "{}" }).then(() => {
      location.href = "/edit";
    });
  };

  const exitStudio = () => {
    if (dirty && !window.confirm("Leave without saving?")) return;
    setStudioMode(null);
    setMotionOpen(false);
  };

  const selectSection = (sectionId: string) => {
    setActiveSectionId(sectionId);
    const el = document.querySelector(`[data-sitepage-section="${sectionId}"]`);
    el?.scrollIntoView({ behavior: "smooth", block: "start" });
  };

  const addSection = (beforeIndex?: number) => {
    if (!doc) return;
    const blank = createBlankProposalPage();
    const pages = [...(doc.pages ?? [])];
    const idx =
      typeof beforeIndex === "number"
        ? Math.max(0, Math.min(pages.length, beforeIndex))
        : pages.length;
    pages.splice(idx, 0, blank);
    const next: PageDocumentV3 = { ...doc, pages };
    setDoc(next);
    setDirty(true);
    setActiveSectionId(blank.id);
  };

  const onMotionProgress = (p: number) => {
    setMotionProgress(p);
    const canvas = document.querySelector(".fk-studio-canvas") as HTMLElement | null;
    if (canvas) {
      const max = canvas.scrollHeight - canvas.clientHeight;
      if (max > 0) canvas.scrollTop = p * max;
    }
  };

  const linksByBlockId = useMemo(() => {
    const map = new Map<string, MotionLink[]>();
    if (!doc) return map;
    for (const sec of doc.pages ?? []) {
      for (const block of sec.blocks ?? []) {
        if (block.links?.length) map.set(block.id, block.links);
      }
    }
    return map;
  }, [doc]);

  const currentPage = pages.find((p) => p.slug === slug);
  const editorPage = useMemo(() => (doc ? toEditorPage(doc) : null), [doc]);

  if (loading && !doc) {
    return (
      <div className="fk-auth-wrap">
        <p className="fk-muted fk-row">
          <Loader2 size={16} className="animate-spin" /> Loading admin…
        </p>
      </div>
    );
  }

  // —— Fullscreen page studio (edit or preview) ——
  if (studioMode && doc && editorPage) {
    const isEdit = studioMode === "edit";
    return (
      <>
      <ProposalBrandingPreviewProvider value={DEFAULT_BRANDING}>
        <MotionRuntimeProvider
          timelines={doc.timelines}
          linksByBlockId={linksByBlockId}
          pins={doc.pins}
          // Edit: keep GSAP off until Motion sheet is open (paused, no initial keyframes).
          enabled={!isEdit || motionOpen}
          applyInitial={!isEdit}
        >
          <div className="fk-studio">
            <header className="fk-studio-bar">
              <Button variant="ghost" size="sm" onClick={exitStudio}>
                <ArrowLeft size={14} /> Pages
              </Button>
              <div className="fk-studio-title">
                <span className="fk-eyebrow">{isEdit ? "Edit" : "Preview"}</span>
                <strong>{currentPage?.title || slug}</strong>
                {dirty ? (
                  <span className="fk-muted" style={{ color: "var(--fk-orange)", fontSize: 12 }}>
                    Unsaved
                  </span>
                ) : null}
              </div>
              <div className="fk-row" style={{ marginLeft: "auto" }}>
                {isEdit ? (
                  <Button
                    variant={motionOpen ? "primary" : "ghost"}
                    size="sm"
                    onClick={() => setMotionOpen((v) => !v)}
                  >
                    <Sparkles size={14} /> Motion
                  </Button>
                ) : null}
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={() => setStudioMode(isEdit ? "preview" : "edit")}
                >
                  {isEdit ? (
                    <>
                      <Eye size={14} /> Preview
                    </>
                  ) : (
                    <>
                      <Pencil size={14} /> Edit
                    </>
                  )}
                </Button>
                {isEdit ? (
                  <Button size="sm" disabled={!dirty || saving} onClick={() => void save()}>
                    {saving ? <Loader2 size={14} className="animate-spin" /> : <Save size={14} />}
                    Save
                  </Button>
                ) : null}
                <a
                  className="fk-btn fk-btn-ghost fk-btn-sm"
                  href={slug === "home" ? "/" : `/${slug}`}
                  target="_blank"
                  rel="noreferrer"
                >
                  Live
                </a>
              </div>
            </header>

            {error ? (
              <p className="fk-err" style={{ padding: "8px 16px" }} role="alert">
                {error}
              </p>
            ) : null}

            <div className={`fk-studio-body${motionOpen ? " is-motion" : ""}`}>
              {isEdit ? (
                <SectionRail
                  doc={doc}
                  activeSectionId={activeSectionId}
                  onSelect={selectSection}
                  onAddSection={motionOpen ? undefined : addSection}
                  mode={motionOpen ? "motion" : "edit"}
                  scrubProgress={motionProgress}
                  onScrubProgress={motionOpen ? onMotionProgress : undefined}
                />
              ) : null}

              <div className="fk-studio-center">
                <div className="fk-studio-canvas" data-finnsk-scroll-root="1">
                  {isEdit ? (
                    <ProposalDocument
                      sections={doc.pages}
                      sectionBackgroundOverrides={doc.pageBackgroundOverrides}
                      proposalSurfaceDefaults={doc.templateSurfaceDefaults}
                      proposalAnimationDefaults={doc.templateAnimationDefaults}
                      timelines={doc.timelines}
                      previewInteractive
                      editorMode="full"
                      layoutMode="website"
                      onPageDraftChange={handleDraftChange}
                      multiPageGap={false}
                      hideSectionInsert
                      activeSectionId={activeSectionId}
                      onActiveSectionIdChange={setActiveSectionId}
                      proposalStudio={proposalStudio}
                    />
                  ) : (
                    <SiteCanvasPreviewProvider>
                      <div className="fk-studio-preview-frame">
                        <ProposalDocument
                          sections={doc.pages}
                          sectionBackgroundOverrides={doc.pageBackgroundOverrides}
                          proposalSurfaceDefaults={doc.templateSurfaceDefaults}
                          proposalAnimationDefaults={doc.templateAnimationDefaults}
                          timelines={doc.timelines}
                          previewInteractive={false}
                          layoutMode="website"
                          multiPageGap={false}
                        />
                      </div>
                    </SiteCanvasPreviewProvider>
                  )}
                </div>

                {isEdit && motionOpen ? (
                  <TimelineSheet
                    open={motionOpen}
                    onClose={() => setMotionOpen(false)}
                    doc={doc}
                    selection={selection}
                    selectedBlockIds={motionBlocks.map((b) => b.blockId)}
                    activeTimelineId={activeTimelineId}
                    onChange={handleDocChange}
                    progress={motionProgress}
                    onProgress={onMotionProgress}
                    pageSlug={slug}
                    onAiApplied={(next) => {
                      setDoc(next);
                      setDirty(true);
                    }}
                  />
                ) : null}
              </div>

              {isEdit && motionOpen ? (
                <MotionRightRail
                  doc={doc}
                  timelines={doc.timelines ?? []}
                  activeTimelineId={activeTimelineId}
                  onSelectTimeline={setActiveTimelineId}
                  onCreateTimeline={createTimeline}
                  selectedBlocks={motionBlocks}
                  onToggleBlock={toggleMotionBlock}
                  onClearSelection={() => setMotionBlocks([])}
                  onAddGroupToTimeline={addGroupToTimeline}
                  onMakeCutout={applyCutoutChrome}
                  onClose={() => setMotionOpen(false)}
                />
              ) : null}
            </div>
          </div>
        </MotionRuntimeProvider>
      </ProposalBrandingPreviewProvider>
      <AgentDock
        pageSlug={slug}
        selection={selection}
        onNavigatePage={(s) => {
          void loadDoc(s);
          void loadPages();
        }}
        onDocumentApplied={(s, document) => {
          if (s === slug && document) {
            setDoc(document as PageDocumentV3);
            setDirty(true);
          } else {
            void loadDoc(s);
          }
          void loadPages();
        }}
        onOpenPageEditor={(s) => {
          void loadDoc(s).then(() => setStudioMode("edit"));
        }}
      />
      </>
    );
  }

  // —— Admin shell (browse + settings) ——
  return (
    <ProposalBrandingPreviewProvider value={DEFAULT_BRANDING}>
      <AdminShell
        section={section}
        onSection={(s) => {
          setStudioMode(null);
          setSection(s);
        }}
        siteName={siteName}
        onLogout={logout}
      >
        {section === "pages" ? (
          <div className="fk-pages-browse">
            <aside className="fk-pages-list" aria-label="Pages">
              <div className="fk-pages-list-head">
                <span className="fk-eyebrow">Pages</span>
                <Button variant="quiet" size="sm" onClick={() => void addPage()}>
                  <Plus size={14} /> Add
                </Button>
              </div>
              <div className="fk-pages-list-body">
                {pages.map((p) => (
                  <button
                    key={p.slug}
                    type="button"
                    className={`fk-page-row${p.slug === slug ? " is-active" : ""}`}
                    onClick={() => void loadDoc(p.slug)}
                  >
                    <FileText size={14} strokeWidth={1.75} />
                    <span className="fk-page-row-title">{p.title || p.slug}</span>
                    {!p.published ? <span className="fk-page-row-badge">Draft</span> : null}
                  </button>
                ))}
              </div>
              <div className="fk-pages-list-foot">
                <Button variant="ghost" size="sm" onClick={() => void renamePage()}>
                  Rename
                </Button>
                <Button variant="ghost" size="sm" onClick={() => void togglePublished()}>
                  {currentPage?.published ? "Unpublish" : "Publish"}
                </Button>
                <Button variant="ghost" size="sm" onClick={() => setPageMetaOpen((v) => !v)}>
                  SEO
                </Button>
                {slug !== "home" ? (
                  <Button variant="ghost" size="sm" onClick={() => void deletePage()}>
                    <Trash2 size={14} />
                  </Button>
                ) : null}
              </div>
              {pageMetaOpen ? (
                <div className="fk-pages-seo">
                  <Field label="Meta title">
                    <Input value={seoTitle} onChange={(e) => setSeoTitle(e.target.value)} />
                  </Field>
                  <Field label="Meta description">
                    <Input value={seoDesc} onChange={(e) => setSeoDesc(e.target.value)} />
                  </Field>
                  <Button size="sm" onClick={() => void saveSeo()}>
                    Save SEO
                  </Button>
                </div>
              ) : null}
            </aside>

            <div className="fk-pages-preview">
              <div className="fk-pages-preview-bar">
                <div>
                  <span className="fk-eyebrow">Preview</span>
                  <strong style={{ display: "block", marginTop: 2 }}>
                    {currentPage?.title || slug}
                  </strong>
                </div>
                <div className="fk-row">
                  <Button size="sm" onClick={() => setStudioMode("edit")}>
                    <Pencil size={14} /> Edit page
                  </Button>
                  <Button variant="ghost" size="sm" onClick={() => setStudioMode("preview")}>
                    <Eye size={14} /> Fullscreen
                  </Button>
                  <a
                    className="fk-btn fk-btn-ghost fk-btn-sm"
                    href={slug === "home" ? "/" : `/${slug}`}
                    target="_blank"
                    rel="noreferrer"
                  >
                    Live
                  </a>
                </div>
              </div>
              {error ? (
                <p className="fk-err" style={{ padding: "8px 16px" }} role="alert">
                  {error}
                </p>
              ) : null}
              {doc && editorPage ? (
                <div className="fk-pages-preview-stage">
                  <SiteCanvasPreviewProvider>
                    <div className="fk-pages-preview-frame">
                      <ProposalDocument
                        sections={doc.pages}
                        sectionBackgroundOverrides={doc.pageBackgroundOverrides}
                        proposalSurfaceDefaults={doc.templateSurfaceDefaults}
                        proposalAnimationDefaults={doc.templateAnimationDefaults}
                        timelines={doc.timelines}
                        previewInteractive={false}
                        layoutMode="website"
                        multiPageGap={false}
                      />
                    </div>
                  </SiteCanvasPreviewProvider>
                </div>
              ) : (
                <div className="fk-empty" style={{ margin: 24 }}>
                  <p className="fk-title" style={{ fontSize: "1.1rem" }}>
                    No document
                  </p>
                </div>
              )}
            </div>
          </div>
        ) : null}

        {section === "design" ? (
          <div>
            <SectionHeader
              title="Design"
              description="Navbar chrome for the public site. Saved to site settings."
              actions={
                <Button size="sm" onClick={() => void saveDesign()}>
                  Save
                </Button>
              }
            />
            <div style={{ padding: 20, maxWidth: 560 }}>
              <Panel>
                <div style={{ padding: 16, display: "flex", flexDirection: "column", gap: 12 }}>
                  <Field label="Site name (nav brand)">
                    <Input
                      value={navDraft.brand || ""}
                      onChange={(e) => setNavDraft((n) => ({ ...n, brand: e.target.value }))}
                    />
                  </Field>
                  <div className="fk-row" style={{ gap: 12 }}>
                    <Field label="Background">
                      <Input
                        type="color"
                        value={navDraft.bgColor || "#ffffff"}
                        onChange={(e) => setNavDraft((n) => ({ ...n, bgColor: e.target.value }))}
                      />
                    </Field>
                    <Field label="Text">
                      <Input
                        type="color"
                        value={navDraft.textColor || "#18181b"}
                        onChange={(e) => setNavDraft((n) => ({ ...n, textColor: e.target.value }))}
                      />
                    </Field>
                    <Field label="Accent">
                      <Input
                        type="color"
                        value={navDraft.accentColor || "#ea580c"}
                        onChange={(e) =>
                          setNavDraft((n) => ({ ...n, accentColor: e.target.value }))
                        }
                      />
                    </Field>
                  </div>
                  <div className="fk-row" style={{ gap: 12 }}>
                    <Field label="Padding Y">
                      <Input
                        type="number"
                        value={navDraft.paddingY ?? 16}
                        onChange={(e) =>
                          setNavDraft((n) => ({ ...n, paddingY: Number(e.target.value) || 0 }))
                        }
                      />
                    </Field>
                    <Field label="Padding X">
                      <Input
                        type="number"
                        value={navDraft.paddingX ?? 24}
                        onChange={(e) =>
                          setNavDraft((n) => ({ ...n, paddingX: Number(e.target.value) || 0 }))
                        }
                      />
                    </Field>
                  </div>
                  <label className="fk-row" style={{ gap: 8, fontSize: 13 }}>
                    <input
                      type="checkbox"
                      checked={navDraft.sticky !== false}
                      onChange={(e) => setNavDraft((n) => ({ ...n, sticky: e.target.checked }))}
                    />
                    Sticky navbar
                  </label>
                  <label className="fk-row" style={{ gap: 8, fontSize: 13 }}>
                    <input
                      type="checkbox"
                      checked={Boolean(navDraft.overlay)}
                      onChange={(e) => setNavDraft((n) => ({ ...n, overlay: e.target.checked }))}
                    />
                    Overlay (transparent over hero)
                  </label>
                  <label className="fk-row" style={{ gap: 8, fontSize: 13 }}>
                    <input
                      type="checkbox"
                      checked={navDraft.borderBottom !== false}
                      onChange={(e) =>
                        setNavDraft((n) => ({ ...n, borderBottom: e.target.checked }))
                      }
                    />
                    Bottom border
                  </label>
                  <Field label="Link active style">
                    <select
                      className="fk-input"
                      value={navDraft.activeStyle || "underline"}
                      onChange={(e) =>
                        setNavDraft((n) => ({
                          ...n,
                          activeStyle: e.target.value as NavbarSettings["activeStyle"],
                        }))
                      }
                    >
                      <option value="underline">Underline</option>
                      <option value="bold">Bold</option>
                      <option value="bg">Background</option>
                    </select>
                  </Field>
                  {designMsg ? (
                    <p className="fk-muted" style={{ marginTop: 4 }}>
                      {designMsg}
                    </p>
                  ) : null}
                </div>
              </Panel>

              <SectionHeader
                title="Block surface"
                description="Default chrome for blocks on the current page. Use Transparent for PNG cutouts."
              />
              <Panel>
                <div style={{ padding: 16, display: "flex", flexDirection: "column", gap: 12 }}>
                  <Field label="Preset">
                    <select
                      className="fk-input"
                      value={surfacePreset}
                      onChange={(e) =>
                        setSurfacePreset(
                          e.target.value as
                            | "transparent"
                            | "transparent_shadow"
                            | "glass"
                            | "solid"
                        )
                      }
                    >
                      <option value="transparent">Transparent (cutouts)</option>
                      <option value="transparent_shadow">Transparent + shadow</option>
                      <option value="glass">Glass</option>
                      <option value="solid">Solid</option>
                    </select>
                  </Field>
                  <p className="fk-muted" style={{ fontSize: 12, margin: 0 }}>
                    Also available via MCP: <code>set_surface_defaults</code>,{" "}
                    <code>set_image_chrome</code> (cutout | framed).
                  </p>
                </div>
              </Panel>
            </div>
          </div>
        ) : null}

        {section === "design" ? (
          <div>
            <SectionHeader
              title="AI & MCP"
              description="BYO Gemini key for inline motion/page plans. MCP token for Cursor and other agents."
              actions={
                <Button size="sm" onClick={() => void saveAi()}>
                  Save AI
                </Button>
              }
            />
            <div style={{ padding: 20, maxWidth: 560 }}>
              <Panel>
                <div style={{ padding: 16 }}>
                <Field label="Provider">
                  <Input value="gemini" disabled />
                </Field>
                <Field label="Model">
                  <Input
                    value={aiModelDraft}
                    onChange={(e) => setAiModelDraft(e.target.value)}
                    placeholder="gemini-2.5-flash"
                    list="fk-gemini-models"
                  />
                  <datalist id="fk-gemini-models">
                    <option value="gemini-2.5-flash" />
                    <option value="gemini-2.0-flash" />
                    <option value="gemini-2.5-flash-lite" />
                    <option value="gemini-flash-latest" />
                  </datalist>
                  <p className="fk-muted" style={{ fontSize: 12, margin: "6px 0 0" }}>
                    Free tier tip: prefer <code>gemini-2.5-flash</code>. Agent auto-retries 503/429 and
                    falls back to other flash models.
                  </p>
                </Field>
                <Field label={aiKeySet ? "Gemini API key (leave blank to keep)" : "Gemini API key"}>
                  <Input
                    type="password"
                    value={aiKeyDraft}
                    onChange={(e) => setAiKeyDraft(e.target.value)}
                    placeholder={aiKeySet ? "•••••••• (set)" : "AIza…"}
                    autoComplete="off"
                  />
                </Field>
                <div className="fk-row" style={{ gap: 8, marginTop: 8 }}>
                  <Button size="sm" variant="ghost" onClick={() => void rotateMcpToken()}>
                    Rotate MCP token
                  </Button>
                </div>
                {mcpToken ? (
                  <Field label="MCP Bearer token">
                    <Input readOnly value={mcpToken} onFocus={(e) => e.currentTarget.select()} />
                  </Field>
                ) : (
                  <p className="fk-muted" style={{ fontSize: 12 }}>
                    Rotate to create a token, then connect Cursor to /mcp.
                  </p>
                )}
                <pre
                  className="fk-panel"
                  style={{ padding: 10, fontSize: 11, overflow: "auto", marginTop: 8 }}
                >{`{
  "mcpServers": {
    "finnsk": {
      "url": "${typeof location !== "undefined" ? location.origin : "https://YOUR.workers.dev"}/mcp",
      "headers": { "Authorization": "Bearer ${mcpToken || "<token>"}" }
    }
  }
}`}</pre>
                {aiMsg ? <p className="fk-muted">{aiMsg}</p> : null}
                </div>
              </Panel>
            </div>
          </div>
        ) : null}

        {section === "domain" ? (
          <div>
            <SectionHeader
              title="Domain"
              description="Attach a custom hostname on this Cloudflare account."
              actions={
                <Button size="sm" onClick={() => void saveDomain()}>
                  Save domain
                </Button>
              }
            />
            <div style={{ padding: 20, maxWidth: 560 }}>
              <div className="fk-panel" style={{ padding: 16 }}>
                <Field label="Hostname">
                  <Input
                    placeholder="www.example.com"
                    value={domainDraft}
                    onChange={(e) => setDomainDraft(e.target.value)}
                  />
                </Field>
                <ol
                  className="fk-muted"
                  style={{ margin: "12px 0 0", paddingLeft: 18, fontSize: 13, lineHeight: 1.6 }}
                >
                  <li>Save the hostname here.</li>
                  <li>Cloudflare → Workers → finnsk-websites-solo → Custom Domains.</li>
                  <li>Or CNAME to your *.workers.dev URL if DNS is elsewhere.</li>
                </ol>
                {domainMsg ? (
                  <p className="fk-muted" style={{ marginTop: 12, fontSize: 13 }}>
                    {domainMsg}
                  </p>
                ) : null}
              </div>
            </div>
          </div>
        ) : null}

        {section === "integrations" ? <IntegrationsPanel /> : null}
      </AdminShell>
      <AgentDock
        pageSlug={slug}
        selection={selection}
        onNavigatePage={(s) => {
          void loadDoc(s);
          void loadPages();
        }}
        onDocumentApplied={(s, document) => {
          if (s === slug && document) {
            setDoc(document as PageDocumentV3);
            setDirty(true);
          } else {
            void loadDoc(s);
          }
          void loadPages();
        }}
        onOpenPageEditor={(s) => {
          void loadDoc(s).then(() => setStudioMode("edit"));
        }}
      />
    </ProposalBrandingPreviewProvider>
  );
}

function IntegrationsPanel() {
  const [modules, setModules] = useState<
    Array<{
      id: string;
      name: string;
      description: string;
      enabled: boolean;
      enabledAt: string | null;
    }>
  >([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [busyId, setBusyId] = useState<string | null>(null);

  const refresh = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const data = await api<{ modules: typeof modules }>("/api/modules");
      setModules(data.modules || []);
    } catch (e) {
      setError(e instanceof Error ? e.message : "Failed to load modules");
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    void refresh();
  }, [refresh]);

  const toggle = async (id: string, enabled: boolean) => {
    setBusyId(id);
    setError(null);
    try {
      await api(`/api/modules/${encodeURIComponent(id)}/${enabled ? "disable" : "enable"}`, {
        method: "POST",
        body: "{}",
      });
      await refresh();
    } catch (e) {
      setError(e instanceof Error ? e.message : "Update failed");
    } finally {
      setBusyId(null);
    }
  };

  const blogEnabled = modules.some((m) => m.id === "blog" && m.enabled);

  return (
    <div>
      <SectionHeader
        title="Integrations"
        description="Modules add D1 tables, blocks, and API routes without forking the core."
      />
      <div style={{ padding: 20 }}>
        {error ? (
          <p className="fk-err" style={{ marginBottom: 12 }} role="alert">
            {error}
          </p>
        ) : null}
        {loading ? (
          <p className="fk-muted fk-row">
            <Loader2 size={14} className="animate-spin" /> Loading modules…
          </p>
        ) : modules.length === 0 ? (
          <div className="fk-empty">
            <p className="fk-eyebrow">Modules</p>
            <h2 className="fk-title" style={{ fontSize: "1.15rem", marginTop: 8 }}>
              No integrations available yet
            </h2>
          </div>
        ) : (
          <div style={{ display: "flex", flexDirection: "column", gap: 10, maxWidth: 640 }}>
            {modules.map((m) => (
              <div
                key={m.id}
                className="fk-panel"
                style={{
                  padding: 16,
                  display: "flex",
                  alignItems: "flex-start",
                  justifyContent: "space-between",
                  gap: 16,
                }}
              >
                <div>
                  <div className="fk-row" style={{ gap: 10 }}>
                    <strong style={{ fontSize: 14 }}>{m.name}</strong>
                    <span
                      className="fk-chip"
                      style={{
                        cursor: "default",
                        borderColor: m.enabled ? "var(--fk-orange)" : undefined,
                        color: m.enabled ? "var(--fk-orange)" : undefined,
                      }}
                    >
                      {m.enabled ? "Enabled" : "Off"}
                    </span>
                  </div>
                  <p className="fk-muted" style={{ marginTop: 6, fontSize: 13 }}>
                    {m.description}
                  </p>
                </div>
                <Button
                  size="sm"
                  variant={m.enabled ? "ghost" : "primary"}
                  disabled={busyId === m.id}
                  onClick={() => void toggle(m.id, m.enabled)}
                >
                  {busyId === m.id ? (
                    <Loader2 size={14} className="animate-spin" />
                  ) : m.enabled ? (
                    "Disable"
                  ) : (
                    "Enable"
                  )}
                </Button>
              </div>
            ))}
          </div>
        )}
        {blogEnabled ? <BlogAdmin /> : null}
      </div>
    </div>
  );
}

function BlogAdmin() {
  const [posts, setPosts] = useState<
    Array<{
      id: string;
      slug: string;
      title: string;
      body_html: string;
      published: number;
    }>
  >([]);
  const [title, setTitle] = useState("");
  const [body, setBody] = useState("");
  const [msg, setMsg] = useState<string | null>(null);

  const refresh = useCallback(async () => {
    const data = await api<{ posts: typeof posts }>("/api/modules/blog/posts?all=1");
    setPosts(data.posts || []);
  }, []);

  useEffect(() => {
    void refresh().catch(() => undefined);
  }, [refresh]);

  const create = async () => {
    setMsg(null);
    try {
      await api("/api/modules/blog/posts", {
        method: "POST",
        body: JSON.stringify({ title, body_html: body, published: true }),
      });
      setTitle("");
      setBody("");
      setMsg("Post created.");
      await refresh();
    } catch (e) {
      setMsg(e instanceof Error ? e.message : "Create failed");
    }
  };

  const remove = async (id: string) => {
    await api(`/api/modules/blog/posts/${encodeURIComponent(id)}`, { method: "DELETE" });
    await refresh();
  };

  return (
    <div style={{ marginTop: 28, maxWidth: 640 }}>
      <h3 className="fk-title" style={{ fontSize: "1.05rem", marginBottom: 12 }}>
        Blog posts
      </h3>
      <Panel>
        <div style={{ padding: 16, display: "flex", flexDirection: "column", gap: 10 }}>
          <Field label="Title">
            <Input value={title} onChange={(e) => setTitle(e.target.value)} />
          </Field>
          <Field label="Body (HTML)">
            <Textarea rows={4} value={body} onChange={(e) => setBody(e.target.value)} />
          </Field>
          <Button size="sm" disabled={!title.trim()} onClick={() => void create()}>
            Create post
          </Button>
          {msg ? (
            <p className="fk-muted" style={{ fontSize: 13 }}>
              {msg}
            </p>
          ) : null}
        </div>
      </Panel>
      <div style={{ marginTop: 12, display: "flex", flexDirection: "column", gap: 8 }}>
        {posts.map((p) => (
          <div
            key={p.id}
            className="fk-panel"
            style={{
              padding: 12,
              display: "flex",
              justifyContent: "space-between",
              gap: 12,
              alignItems: "center",
            }}
          >
            <div>
              <strong style={{ fontSize: 13 }}>{p.title}</strong>
              <p className="fk-muted" style={{ fontSize: 12 }}>
                /{p.slug} · {p.published ? "Published" : "Draft"}
              </p>
            </div>
            <Button size="sm" variant="ghost" onClick={() => void remove(p.id)}>
              <Trash2 size={14} />
            </Button>
          </div>
        ))}
      </div>
    </div>
  );
}
